import RealityKit
import SwiftUI
import UIKit

/// Builds the passport book scene (iOS 18+).
///
/// The geometry comes from `Passport.usdz`, generated by
/// `Packages/PassportContent/Blender/make_passport.py`; the dimensions and
/// prim names below mirror that script. Everything per user is applied
/// here: the cover leather in the nationality's colour family, the foil
/// title and crest, and a paper texture per page face carrying the
/// identity page and the stamps.
///
/// Frames: Blender's Y-up conversion is a rotation on the root prim, so
/// every part keeps Blender's frame locally: X across the width, Z up the
/// page, and depth toward the viewer along -Y. Hinges therefore turn about
/// local Z, and anything attached to a part is placed in that frame.
@available(iOS 18.0, *)
@MainActor
enum PassportScene {

    // Dimensions in metres, mirroring make_passport.py.
    static let coverWidth: Float = 0.088
    static let coverHeight: Float = 0.125
    static let boardThickness: Float = 0.0016
    static let blockThickness: Float = 0.0036
    static let coverBevel: Float = 0.0005
    static var hingeDepth: Float { boardThickness + blockThickness / 2 }
    static var closedDepth: Float { 2 * boardThickness + blockThickness }
    static let sheetCount = 3

    /// Page faces in reading order, by prim name. The two blocks carry a
    /// second material for their page edges.
    static let faceNames = [
        "LeftBlock", "Sheet1Front", "Sheet1Back", "Sheet2Front", "Sheet2Back", "Sheet3Front", "Sheet3Back", "RightBlock"
    ]

    static let pageTextureSize = CGSize(width: 768, height: 1092)
    static let coverTextureSize = CGSize(width: 1024, height: 1456)

    enum Failure: Error {
        case partMissing(String)
    }

    static func build(
        in content: inout RealityViewCameraContent,
        book: PassportBook,
        motion: PassportMotion
    ) async throws {
        // Camera: framed on the open spread at the view's 1.45 aspect.
        let camera = PerspectiveCamera()
        camera.camera.fieldOfViewInDegrees = 30
        // Pages sit a fraction of a millimetre apart, so the depth range is
        // kept tight around the book or the sheet beneath fights through.
        camera.camera.near = 0.12
        camera.camera.far = 0.5
        camera.position = [0, 0, 0.27]
        content.add(camera)

        let lightSource = await RealityStudio.addLighting(to: &content, name: "passport-studio", keyFrom: [-0.3, 0.5, 0.8])

        let model = try await Entity(named: "Passport")
        guard let coverPivot = model.findEntity(named: "FrontCoverPivot") else { throw Failure.partMissing("FrontCoverPivot") }
        var sheets: [Entity] = []
        for index in 1...sheetCount {
            guard let sheet = model.findEntity(named: "Sheet\(index)") else { throw Failure.partMissing("Sheet\(index)") }
            sheets.append(sheet)
        }

        // Covers.
        let leather = leather(for: book.coverFamily)
        for name in ["FrontCover", "BackCover"] {
            for part in modelParts(named: name, in: model) {
                setMaterials(of: part) { _ in [leather] }
            }
        }
        if let cover = modelParts(named: "FrontCover", in: model).first,
           let mask = try? await RealityStudio.maskTexture(PassportCoverArtwork(book: book), size: coverTextureSize) {
            let inset = coverBevel * 2
            let plane = MeshResource.generatePlane(width: coverWidth - inset, height: coverHeight - inset)
            let foil = ModelEntity(mesh: plane, materials: [foil(mask)])
            // In the part's frame: centred on the cover, a hair in front of
            // its outer face, turned from +Z to face the viewer at -Y.
            foil.position = [coverWidth / 2, -(closedDepth + 0.00015), coverHeight / 2]
            foil.orientation = simd_quatf(angle: .pi / 2, axis: [1, 0, 0])
            cover.addChild(foil)
        }

        // Pages. Blank faces share one texture.
        let edges = pageEdges()
        var blankPaper: PhysicallyBasedMaterial?
        for (face, page) in zip(faceNames, PassportPages.pages(for: book.stamps)) {
            let material: PhysicallyBasedMaterial
            if case .blank = page {
                if blankPaper == nil { blankPaper = try await paper(for: page, book: book) }
                material = blankPaper!
            } else {
                material = try await paper(for: page, book: book)
            }
            for part in modelParts(named: face, in: model) {
                setMaterials(of: part) { existing in existing.count > 1 ? [material, edges] : [material] }
            }
        }

        if let lightSource {
            for part in allModelParts(in: model) {
                part.components.set(ImageBasedLightReceiverComponent(imageBasedLight: lightSource))
            }
        }

        // `root` tilts with the drag; `model` is offset inside it so the
        // camera target stays at the spread's centre, closed or open.
        let root = Entity()
        root.addChild(model)
        content.add(root)

        motion.attach(root: root, book: model, coverPivot: coverPivot, sheets: sheets)
        motion.subscription = content.subscribe(to: SceneEvents.Update.self) { event in
            motion.tick(event.deltaTime)
        }
    }

    // MARK: Parts

    private static func modelParts(named name: String, in root: Entity) -> [Entity] {
        allModelParts(in: root).filter { $0.name == name }
    }

    private static func allModelParts(in root: Entity) -> [Entity] {
        var found: [Entity] = []
        func walk(_ entity: Entity) {
            if entity.components.has(ModelComponent.self) { found.append(entity) }
            for child in entity.children { walk(child) }
        }
        walk(root)
        return found
    }

    private static func setMaterials(of entity: Entity, _ transform: ([any RealityKit.Material]) -> [any RealityKit.Material]) {
        guard var component = entity.components[ModelComponent.self] else { return }
        component.materials = transform(component.materials)
        entity.components.set(component)
    }

    // MARK: Materials
    //
    // Albedos are material properties, not UI colours, so they are
    // deliberately literals here.

    private static func leather(for family: PassportCoverFamily) -> PhysicallyBasedMaterial {
        let tint: UIColor = switch family {
        case .burgundy: UIColor(red: 0.40, green: 0.08, blue: 0.13, alpha: 1)
        case .navy: UIColor(red: 0.07, green: 0.11, blue: 0.30, alpha: 1)
        case .green: UIColor(red: 0.07, green: 0.27, blue: 0.17, alpha: 1)
        case .black: UIColor(red: 0.07, green: 0.07, blue: 0.08, alpha: 1)
        case .red: UIColor(red: 0.66, green: 0.10, blue: 0.14, alpha: 1)
        }
        var material = PhysicallyBasedMaterial()
        material.baseColor = .init(tint: tint)
        material.metallic = .init(floatLiteral: 0)
        material.roughness = .init(floatLiteral: 0.62)
        material.clearcoat = .init(floatLiteral: 0.12)
        material.clearcoatRoughness = .init(floatLiteral: 0.55)
        return material
    }

    private static func pageEdges() -> PhysicallyBasedMaterial {
        var material = PhysicallyBasedMaterial()
        material.baseColor = .init(tint: UIColor(red: 0.92, green: 0.90, blue: 0.84, alpha: 1))
        material.metallic = .init(floatLiteral: 0)
        material.roughness = .init(floatLiteral: 0.95)
        return material
    }

    private static func paper(for page: PassportPage, book: PassportBook) async throws -> PhysicallyBasedMaterial {
        let texture = try await RealityStudio.colorTexture(PassportPageArtwork(page: page, book: book), size: pageTextureSize)
        var material = PhysicallyBasedMaterial()
        material.baseColor = .init(tint: .white, texture: .init(texture))
        material.metallic = .init(floatLiteral: 0)
        material.roughness = .init(floatLiteral: 0.9)
        return material
    }

    /// Gold foil cut to the cover artwork.
    private static func foil(_ mask: TextureResource) -> PhysicallyBasedMaterial {
        var material = RealityStudio.metal(UIColor(red: 0.98, green: 0.80, blue: 0.40, alpha: 1), roughness: 0.35)
        material.blending = .transparent(opacity: .init(scale: 1, texture: .init(mask)))
        return material
    }
}

// MARK: - Motion

/// Drives the book every frame: the cover and each sheet spring between
/// closed and turned, the whole book tilts with a drag and sways gently at
/// rest. `spread` 0 is closed, 1 is the cover open on the identity page,
/// and each further step turns one sheet.
@available(iOS 18.0, *)
@MainActor
final class PassportMotion {

    var reduceMotion = false
    var subscription: EventSubscription?
    var onSpreadChange: ((Int) -> Void)?

    private(set) var spread = 0
    var maxSpread: Int { sheets.count + 1 }

    private var root: Entity?
    private var book: Entity?
    private var coverPivot: Entity?
    private var sheets: [Entity] = []

    /// Hinge positions: 0 lying on the right-hand stack, 1 turned onto the left.
    private(set) var cover: Float = 0
    private(set) var sheetAngles: [Float] = []
    private var coverVelocity: Float = 0
    private var sheetVelocities: [Float] = []
    private var pitch: Float = 0, pitchVelocity: Float = 0
    private var yaw: Float = 0, yawVelocity: Float = 0
    private var dragPitch: Float = 0, dragYaw: Float = 0
    private var dragging = false
    private var time: Float = 0

    func attach(root: Entity, book: Entity, coverPivot: Entity, sheets: [Entity]) {
        self.root = root
        self.book = book
        self.coverPivot = coverPivot
        self.sheets = sheets
        sheetAngles = Array(repeating: 0, count: sheets.count)
        sheetVelocities = sheetAngles
        apply()
    }

    func open() { setSpread(1) }
    func next() { setSpread(min(spread + 1, maxSpread)) }
    func previous() { setSpread(max(spread - 1, 0)) }

    private func setSpread(_ value: Int) {
        guard value != spread else { return }
        let coverMoves = spread == 0 || value == 0
        spread = value
        if coverMoves { HapticFeedback.medium() } else { HapticFeedback.light() }
        onSpreadChange?(value)
        if reduceMotion { snap() }
    }

    /// Tilt the book while the finger is down.
    func dragChanged(translation: CGSize) {
        dragging = true
        dragYaw = max(-0.35, min(0.35, Float(translation.width) * 0.004))
        dragPitch = max(-0.3, min(0.3, Float(translation.height) * -0.004))
    }

    func dragEnded() {
        dragging = false
    }

    func tick(_ deltaTime: Double) {
        let dt = Float(min(deltaTime, 1 / 30))
        time += dt

        if reduceMotion {
            snap()
        } else {
            spring(&cover, &coverVelocity, toward: coverTarget, dt: dt, stiffness: 55, damping: 9)
            land(&cover, &coverVelocity, ceiling: 1)
            for index in sheets.indices {
                spring(&sheetAngles[index], &sheetVelocities[index], toward: sheetTarget(index), dt: dt, stiffness: 50, damping: 8.5)
                let above = index == 0 ? cover : sheetAngles[index - 1]
                land(&sheetAngles[index], &sheetVelocities[index], ceiling: above)
            }
        }

        let idleYaw: Float = reduceMotion ? 0 : sin(time * 0.7) * 0.05
        let idlePitch: Float = reduceMotion ? 0 : sin(time * 0.5 + 1) * 0.03
        spring(&yaw, &yawVelocity, toward: (dragging ? dragYaw : 0) + idleYaw, dt: dt, stiffness: 40, damping: 9)
        spring(&pitch, &pitchVelocity, toward: (dragging ? dragPitch : 0) + idlePitch, dt: dt, stiffness: 40, damping: 9)
        apply()
    }

    private var coverTarget: Float { spread >= 1 ? 1 : 0 }
    private func sheetTarget(_ index: Int) -> Float { spread >= index + 2 ? 1 : 0 }

    private func snap() {
        cover = coverTarget
        coverVelocity = 0
        for index in sheets.indices {
            sheetAngles[index] = sheetTarget(index)
            sheetVelocities[index] = 0
        }
    }

    /// Hinges run along the parts' local Z (up the spine); a negative angle
    /// swings toward the camera.
    private func apply() {
        coverPivot?.orientation = simd_quatf(angle: -cover * .pi, axis: [0, 0, 1])
        for (index, sheet) in sheets.enumerated() {
            sheet.orientation = simd_quatf(angle: -sheetAngles[index] * .pi, axis: [0, 0, 1])
        }
        // Closed, the book spans x 0...W; open, -W...W. Keep its centre on the camera target.
        book?.position = [
            -PassportScene.coverWidth / 2 * (1 - cover),
            -PassportScene.coverHeight / 2,
            -PassportScene.hingeDepth
        ]
        root?.orientation = simd_quatf(angle: pitch, axis: [1, 0, 0]) * simd_quatf(angle: yaw, axis: [0, 1, 0])
    }

    /// Leaves rest on what is beneath them. The springs are lively, so left
    /// alone a leaf swings past flat and sinks through the stack, and the
    /// page below shows through it. Instead it lands on its stop with a
    /// small rebound. `ceiling` is the leaf above it in the closed stack
    /// (the cover, or the sheet before), which it cannot pass either.
    private func land(_ value: inout Float, _ velocity: inout Float, ceiling: Float) {
        let landed = min(max(value, 0), ceiling)
        guard landed != value else { return }
        value = landed
        velocity *= -0.2
    }

    private func spring(_ value: inout Float, _ velocity: inout Float, toward target: Float, dt: Float, stiffness: Float, damping: Float) {
        velocity += (stiffness * (target - value) - damping * velocity) * dt
        value += velocity * dt
    }
}

// MARK: - Artwork
//
// These views are rendered to textures, so sizes are texture pixels and the
// colours are paper and ink albedos rather than UI tokens. Both are
// deliberately fixed.

/// Foil layer for the front cover, drawn white on clear as an opacity mask.
private struct PassportCoverArtwork: View {
    let book: PassportBook

    var body: some View {
        VStack(spacing: 0) {
            Text("OUEST")
                .font(.system(size: 34, weight: .semibold))
                .tracking(14)
                .padding(.top, 130)
            Spacer()
            ZStack {
                ShieldShape()
                    .stroke(lineWidth: 8)
                    .frame(width: 300, height: 340)
                Text("O")
                    .font(.custom("Fraunces", size: 210))
                    .fontWeight(.bold)
                    .offset(y: -18)
            }
            Spacer()
            VStack(spacing: 10) {
                Text(book.country?.name ?? "Traveller")
                    .font(.custom("Fraunces", size: 74))
                    .fontWeight(.semibold)
                    .multilineTextAlignment(.center)
                    .lineLimit(2)
                    .minimumScaleFactor(0.6)
                Text("PASSPORT")
                    .font(.system(size: 58, weight: .bold))
                    .tracking(12)
            }
            Spacer()
            ChipSymbol()
                .frame(width: 124, height: 86)
                .padding(.bottom, 120)
        }
        .padding(.horizontal, 90)
    }
}

/// A plain shield: the Ouest crest, not any nation's arms.
private struct ShieldShape: Shape {
    func path(in rect: CGRect) -> Path {
        var path = Path()
        let w = rect.width, h = rect.height
        path.move(to: CGPoint(x: rect.minX, y: rect.minY))
        path.addLine(to: CGPoint(x: rect.maxX, y: rect.minY))
        path.addLine(to: CGPoint(x: rect.maxX, y: rect.minY + h * 0.58))
        path.addQuadCurve(to: CGPoint(x: rect.midX, y: rect.maxY), control: CGPoint(x: rect.maxX, y: rect.minY + h * 0.92))
        path.addQuadCurve(to: CGPoint(x: rect.minX, y: rect.minY + h * 0.58), control: CGPoint(x: rect.minX, y: rect.minY + h * 0.92))
        path.closeSubpath()
        _ = w
        return path
    }
}

/// The e-passport chip mark.
private struct ChipSymbol: View {
    var body: some View {
        Canvas { context, size in
            let stroke = StrokeStyle(lineWidth: 8, lineCap: .round)
            let frame = CGRect(origin: .zero, size: size).insetBy(dx: 4, dy: 4)
            context.stroke(Path(roundedRect: frame, cornerRadius: 10), with: .color(.white), style: stroke)
            let r = size.height * 0.2
            let centre = CGPoint(x: size.width / 2, y: size.height / 2)
            context.stroke(Path(ellipseIn: CGRect(x: centre.x - r, y: centre.y - r, width: r * 2, height: r * 2)), with: .color(.white), style: stroke)
            var lines = Path()
            lines.move(to: CGPoint(x: frame.minX, y: centre.y))
            lines.addLine(to: CGPoint(x: centre.x - r, y: centre.y))
            lines.move(to: CGPoint(x: centre.x + r, y: centre.y))
            lines.addLine(to: CGPoint(x: frame.maxX, y: centre.y))
            context.stroke(lines, with: .color(.white), style: stroke)
        }
    }
}

/// One page face: cream paper with a faint security pattern and the content.
private struct PassportPageArtwork: View {
    let page: PassportPage
    let book: PassportBook

    static let paper = Color(red: 0.96, green: 0.94, blue: 0.89)
    static let pattern = Color(red: 0.62, green: 0.68, blue: 0.80)
    static let ink = Color(red: 0.16, green: 0.18, blue: 0.24)

    var body: some View {
        ZStack {
            Self.paper
            securityPattern.opacity(0.3)
            switch page {
            case .identity:
                IdentityPageArtwork(book: book)
            case .stamps(let stamps, let number):
                StampsPageArtwork(stamps: stamps)
                pageNumber(number)
            case .blank:
                EmptyView()
            }
        }
        .foregroundStyle(Self.ink)
    }

    private func pageNumber(_ number: Int) -> some View {
        VStack {
            Spacer()
            Text("\(number)")
                .font(.system(size: 22, weight: .medium, design: .serif))
                .opacity(0.5)
                .padding(.bottom, 36)
        }
    }

    /// Wavy guilloché-like lines across the whole page.
    private var securityPattern: some View {
        Canvas { context, size in
            for row in stride(from: CGFloat(0), through: size.height, by: 16) {
                var path = Path()
                path.move(to: CGPoint(x: 0, y: row))
                for x in stride(from: CGFloat(0), through: size.width, by: 6) {
                    path.addLine(to: CGPoint(x: x, y: row + sin(x / 38 + row / 28) * 5))
                }
                context.stroke(path, with: .color(Self.pattern), lineWidth: 1)
            }
        }
    }
}

private struct IdentityPageArtwork: View {
    let book: PassportBook

    var body: some View {
        VStack(alignment: .leading, spacing: 30) {
            Text("OUEST")
                .font(.system(size: 26, weight: .semibold))
                .tracking(10)
                .opacity(0.6)
            Text("Passport")
                .font(.custom("Fraunces", size: 92))
                .fontWeight(.bold)
            Rectangle()
                .frame(height: 2)
                .opacity(0.4)
            field("HOLDER", book.holderName.uppercased())
            field("NATIONALITY", nationality)
            if let memberSince = book.memberSince {
                field("MEMBER SINCE", memberSince.formatted(.dateTime.month(.wide).year()).uppercased())
            }
            field("STAMPS", "\(book.stamps.count)")
            Spacer()
            VStack(alignment: .leading, spacing: 4) {
                Text(machineReadable(line: 1))
                Text(machineReadable(line: 2))
            }
            .font(.system(size: 31, weight: .regular, design: .monospaced))
            .lineLimit(1)
            .minimumScaleFactor(0.5)
        }
        .padding(64)
    }

    private var nationality: String {
        guard let country = book.country else { return "TRAVELLER" }
        return "\(country.flag) \(country.name.uppercased())"
    }

    private func field(_ label: String, _ value: String) -> some View {
        VStack(alignment: .leading, spacing: 6) {
            Text(label)
                .font(.system(size: 20, weight: .semibold))
                .tracking(4)
                .opacity(0.55)
            Text(value)
                .font(.system(size: 36, weight: .medium))
                .lineLimit(1)
                .minimumScaleFactor(0.6)
        }
    }

    /// Two lines in the style of a passport's machine-readable zone.
    private func machineReadable(line: Int) -> String {
        let fill = Character("<")
        let name = book.holderName.uppercased()
            .replacingOccurrences(of: " ", with: "<")
            .filter { $0.isLetter || $0 == fill }
        let code = book.country?.code ?? "OUE"
        let text = line == 1 ? "P<\(code)\(name)" : "OUEST\(book.stamps.count)\(code)"
        return String(text.prefix(30)).padding(toLength: 30, withPad: String(fill), startingAt: 0)
    }
}

private struct StampsPageArtwork: View {
    let stamps: [PassportStamp]

    var body: some View {
        GeometryReader { geometry in
            ForEach(Array(stamps.enumerated()), id: \.element.id) { index, stamp in
                let column = CGFloat(index % 2), row = CGFloat(index / 2)
                let jitter = CGFloat(stamp.rotationDegrees)
                StampArtwork(stamp: stamp)
                    .frame(width: geometry.size.width * 0.46, height: geometry.size.height * 0.30)
                    .rotationEffect(.degrees(stamp.rotationDegrees))
                    .position(
                        x: geometry.size.width * (0.28 + 0.44 * column) + jitter * 1.4,
                        y: geometry.size.height * (0.24 + 0.34 * row) + jitter
                    )
            }
        }
    }
}

private struct StampArtwork: View {
    let stamp: PassportStamp

    var body: some View {
        ZStack {
            outline.stroke(lineWidth: 7)
            outline.stroke(lineWidth: 2.5).padding(10)
            VStack(spacing: 7) {
                Text(countryName)
                    .font(.system(size: 24, weight: .heavy))
                    .tracking(3)
                Text(stamp.destination)
                    .font(.custom("Fraunces", size: 36))
                    .fontWeight(.semibold)
                if let arrival = stamp.arrival {
                    Text("ARRIVED  \(short(arrival))")
                }
                if let departure = stamp.departure {
                    Text("DEPARTED \(short(departure))")
                }
                Text(stamp.countryCode.map(CountryHelper.flag(for:)) ?? "✈︎")
                    .font(.system(size: 30))
            }
            .font(.system(size: 19, weight: .semibold, design: .monospaced))
            .lineLimit(1)
            .minimumScaleFactor(0.55)
            .padding(.horizontal, 30)
            .padding(.vertical, 24)
        }
        .foregroundStyle(inkColor)
        .opacity(0.86)
    }

    private var countryName: String {
        stamp.countryCode.flatMap { CountryHelper.country(for: $0)?.name.uppercased() } ?? "ENTRY"
    }

    private func short(_ date: Date) -> String {
        date.formatted(.dateTime.day(.twoDigits).month(.abbreviated).year()).uppercased()
    }

    private var outline: AnyShape {
        switch stamp.shape {
        case .rectangle: AnyShape(RoundedRectangle(cornerRadius: 18, style: .continuous))
        case .oval: AnyShape(Ellipse())
        case .circle: AnyShape(Circle())
        case .hexagon: AnyShape(Hexagon())
        }
    }

    // Stamp inks: texture albedos, deliberately literal.
    private var inkColor: Color {
        switch stamp.ink {
        case .red: Color(red: 0.72, green: 0.16, blue: 0.19)
        case .blue: Color(red: 0.15, green: 0.28, blue: 0.62)
        case .green: Color(red: 0.10, green: 0.42, blue: 0.30)
        case .violet: Color(red: 0.38, green: 0.21, blue: 0.55)
        }
    }
}

private struct Hexagon: Shape {
    func path(in rect: CGRect) -> Path {
        var path = Path()
        let cx = rect.midX, cy = rect.midY
        let rx = rect.width / 2, ry = rect.height / 2
        for index in 0..<6 {
            let angle = CGFloat(index) / 6 * 2 * .pi
            let point = CGPoint(x: cx + cos(angle) * rx, y: cy + sin(angle) * ry)
            if index == 0 { path.move(to: point) } else { path.addLine(to: point) }
        }
        path.closeSubpath()
        return path
    }
}
